// Normaliza, valida y puntua el lead. Reglas identicas a la demo del portfolio.
const DEC = /(direcci[oó]n|directora|director|gerente|gerencia|ceo|fundador|fundadora|propietari|due[ñn]o|socio)/i;
const RESP = /(responsable|jefe|head|manager|coordinador)/i;
const FUENTES = { 'referido': 30, 'evento': 20, 'web': 20, 'linkedin': 15, 'email frio': 5 };
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

return $input.all().map((item) => {
  const b = item.json.body || item.json;
  const email = String(b.email || '').trim().toLowerCase();
  const emailOk = EMAIL.test(email);
  const telefono = String(b.telefono || '').replace(/[^\d+]/g, '');
  const fuente = String(b.fuente || '').trim().toLowerCase();
  const empleados = Number(b.empleados) || 0;
  const cargo = String(b.cargo || '').trim();

  let score = FUENTES[fuente] ?? 5;
  score += empleados >= 51 ? 15 : empleados >= 11 ? 20 : 10;
  score += DEC.test(cargo) ? 25 : RESP.test(cargo) ? 15 : 5;
  score += telefono.length >= 9 ? 10 : 0;
  if (!emailOk) score -= 20;
  score = Math.max(0, Math.min(100, score));

  return {
    json: {
      nombre: String(b.nombre || '').trim(),
      empresa: String(b.empresa || '').trim(),
      cargo,
      email,
      emailOk,
      telefono,
      fuente,
      empleados,
      score,
      nivel: score >= 70 ? 'caliente' : score >= 40 ? 'templado' : 'frio',
      estado: 'Nuevo',
      fecha_alta: new Date().toISOString().slice(0, 10),
    },
  };
});
